frappe.ui.form.on('Item', {
    refresh: function(frm) {
        // Run calculation when the form loads
        calculate_margin_amount(frm);
    },
    valuation_rate: function(frm) {
        calculate_margin_amount(frm);
    },
    standard_rate: function(frm) {
        calculate_margin_amount(frm);
    }
});

function calculate_margin_amount(frm) {
    // Get values and convert to float (number)
    // ERPNext uses 'standard_rate' for the field "Standard Selling Rate"
    let val_rate = flt(frm.doc.valuation_rate);
    let sell_rate = flt(frm.doc.standard_rate);
    
    // Calculate the difference
    let margin = sell_rate - val_rate;
    
    // Set the value into your field
    // Ensure the "Name" in Customize Form is exactly 'custom_margin'
    frm.set_value('custom_margin', margin);
}

frappe.ui.form.on("Sales Invoice Item", {

    barcode_scan: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.barcode_scan) return;

        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Item Barcode",
                filters: {
                    barcode: row.barcode_scan
                },
                fields: ["parent", "uom"]
            },

            callback: function(r) {

                if (r.message && r.message.length) {

                    let d = r.message[0];

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "item_code",
                        d.parent
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "uom",
                        d.uom
                    );

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        "qty",
                        1
                    );

                    frm.refresh_field("items");
                }
            }
        });
    }
});

