frappe.ui.form.on('Item', {
    // 1. When you change the rate in the header
    custom_default_purchase_rate: function(frm) {
        calculate_child_rates(frm);
    }
});

// 2. When you add a new row or change the conversion factor in the table
frappe.ui.form.on('Retail Packing Detail', {
    conversion_factor: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let base_rate = frm.doc.custom_default_purchase_rate || 0;
        
        // Calculate: Header Rate * Conversion Factor
        let calculated_rate = base_rate * (row.conversion_factor || 1);
        
        frappe.model.set_value(cdt, cdn, 'purchase_rate', calculated_rate);
    },
    
    // Trigger calculation when a new row is added
    custom_retail_packing_detail_add: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let base_rate = frm.doc.custom_default_purchase_rate || 0;
        frappe.model.set_value(cdt, cdn, 'purchase_rate', base_rate);
    }
});

// Helper function to update ALL rows if the header rate changes
function calculate_child_rates(frm) {
    let base_rate = frm.doc.custom_default_purchase_rate || 0;
    
    $.each(frm.doc.custom_retail_packing_detail || [], function(i, row) {
        let calculated_rate = base_rate * (row.conversion_factor || 1);
        frappe.model.set_value(row.doctype, row.name, 'purchase_rate', calculated_rate);
    });
}

frappe.ui.form.on('Item', {

    custom_scale_item: function(frm) {

        if (frm.doc.custom_scale_item) {

            if (!frm.doc.custom_barcode) {

                let prefix = "21";
                let rand = Math.floor(10000 + Math.random() * 90000);

                frm.set_value(
                    'custom_barcode',
                    prefix + rand
                );
            }
        }
    }

});

frappe.ui.form.on('Item', {
    refresh: function(frm) {
        calculate_margins(frm);
    },
    valuation_rate: function(frm) {
        calculate_margins(frm);
    },
    standard_rate: function(frm) {
        calculate_margins(frm);
    }
});

function calculate_margins(frm) {
    // 1. Get values and convert to float
    let val_rate = flt(frm.doc.valuation_rate);
    let sell_rate = flt(frm.doc.standard_rate);
    
    // 2. Calculate the Absolute Margin Amount
    let margin_amt = sell_rate - val_rate;
    frm.set_value('custom_margin', margin_amt);
    
    // 3. Calculate Margin Percentage
    // We check if sell_rate is greater than 0 to avoid "Division by Zero" errors
    if (sell_rate > 0) {
        let margin_pct = (margin_amt / sell_rate) * 100;
        frm.set_value('custom_margin_', margin_pct);
    } else {
        // If selling price is 0, margin % is technically 0 or undefined
        frm.set_value('custom_margin_', 0);
    }
}


// If your business uses Markup instead, change the line in the script to:
// let margin_pct = (margin_amt / val_rate) * 100; (and check that val_rate > 0).

frappe.ui.form.on('Item', {
    custom_warranty: function(frm) {
        if (!frm.doc.custom_warranty) {
            frm.set_value('custom_in_months', null);
        }
    }
});
